import manifest from "@/content/image-manifest.json";

interface ManifestEntry {
  /** Intrinsic width of the original file */
  w: number;
  /** Intrinsic height of the original file */
  h: number;
  /** Widths of the smaller variants generated by `npm run images` */
  v: number[];
}

const entries = manifest as Record<string, ManifestEntry>;

export interface ResolvedImage {
  /** Original, full-size file */
  full: string;
  /** Best default `src`: the largest generated variant, or the original */
  src: string;
  srcSet: string | undefined;
  width: number;
  height: number;
}

/** Looks up a file under /public/images and returns everything an <img> needs. */
export function resolveImage(path: string): ResolvedImage {
  const entry = entries[path];
  if (!entry) {
    throw new Error(`Image "${path}" is not in the manifest. Run "npm run images" after adding files.`);
  }

  const variant = (width: number) => path.replace(/\.webp$/, `.w${width}.webp`);
  const largest = entry.v.at(-1);

  return {
    full: path,
    src: largest ? variant(largest) : path,
    srcSet: entry.v.length
      ? [...entry.v.map((width) => `${variant(width)} ${width}w`), `${path} ${entry.w}w`].join(", ")
      : undefined,
    width: entry.w,
    height: entry.h,
  };
}

export function shotPath(slug: string, file: string) {
  return `/images/work/${slug}/${file}.webp`;
}
